update public.learning_paths
set
  title = 'Theater History I',
  goal = 'Theater History I',
  summary = 'This course surveys theater and performance from ancient Mediterranean traditions through the 18th century, while training students to think like theater historians. Students study plays, performance spaces, actors, audiences, institutions, technologies, and archival traces across Western and selected global traditions. The course emphasizes how theater history is constructed, whose performances are preserved, and how historical knowledge can inform contemporary theater practice.',
  data = $thi1json${"slug": "theater-history-i", "title": "Theater History I", "description": "This course surveys theater and performance from ancient Mediterranean traditions through the 18th century, while training students to think like theater historians. Students study plays, performance spaces, actors, audiences, institutions, technologies, and archival traces across Western and selected global traditions. The course emphasizes how theater history is constructed, whose performances are preserved, and how historical knowledge can inform contemporary theater practice.", "topics": [{"id": "052004d7-1633-4422-bfd9-2bac9b579111", "type": "topic", "title": "Theater Historiography and Research Methods", "description": "A world-class theater history course starts by asking how history is made. Students learn that theater history is reconstructed from scripts, buildings, images, reviews, account books, censorship records, costumes, oral traditions, and performance traces rather than from performance itself.", "children": [{"id": "445351fb-222a-41ba-8855-2ecb2aae11bc", "type": "subtopic", "title": "What counts as evidence", "children": [{"id": "2f0c87f5-6c71-4a82-86f4-59254aa41753", "type": "concept", "title": "Playtexts and manuscripts"}, {"id": "bc29bc32-90a7-47b4-8be9-49af663acf22", "type": "concept", "title": "Archaeological remains"}, {"id": "dbf7a4ca-4393-424c-9cf1-958fe40f88bc", "type": "concept", "title": "Iconography"}, {"id": "a6df0c6d-2e76-4457-97fb-18b22f43e93c", "type": "concept", "title": "Reviews and eyewitness accounts"}], "description": "Why learn it: Students learn to read different kinds of historical evidence and understand what each source can and cannot prove."}, {"id": "cb59d71f-e34f-4095-b964-2363dbb6638c", "type": "subtopic", "title": "Historiography and canon formation", "children": [{"id": "9e8176bc-2217-4c7f-9768-e8dfde58d59d", "type": "concept", "title": "Whose work was preserved"}, {"id": "4d241585-95a5-4e6f-b851-48de83949eb2", "type": "concept", "title": "Translation and adaptation"}, {"id": "5586a9d8-29fb-45e9-9819-3cff09a3129f", "type": "concept", "title": "National theater narratives"}, {"id": "01ede9f6-5acf-4135-875c-eb2a3293299e", "type": "concept", "title": "Missing or suppressed records"}], "description": "Why learn it: The point is to see theater history as an argument shaped by archives, institutions, colonial histories, translation, and access."}, {"id": "ba555745-9952-4c7c-80e3-63b658c40842", "type": "subtopic", "title": "Research habits", "children": [{"id": "bdcaf1a1-5c93-4628-9f0a-d36299c4c199", "type": "concept", "title": "Primary vs. secondary sources"}, {"id": "a8f658c9-ab70-4e9e-b87a-2ce957bf83e4", "type": "concept", "title": "Annotated bibliography"}, {"id": "7c7d7c13-d6c4-407f-8dd5-b8d8ed285243", "type": "concept", "title": "Museum collections"}, {"id": "ce1d6c4e-d58c-48db-8710-7fa2f1ca0bb0", "type": "concept", "title": "Scholarly databases"}], "description": "Why learn it: Students practice citation, source evaluation, and responsible use of digital archives."}]}, {"id": "03e5bb9c-128b-42b4-a976-d8ae45ae05cd", "type": "topic", "title": "Greek Theater and Tragedy", "description": "Greek theater gives students a foundation in Western dramatic structure, civic performance, festival culture, chorus, myth, and architectural conventions. The goal is not reverence alone, but historical understanding of how tragedy functioned in its own society.", "children": [{"id": "08ef3fb8-0a3b-4a77-88af-3d9cb5c6c6f8", "type": "subtopic", "title": "Dionysian festivals and civic context", "children": [{"id": "c294efdd-8b05-4a26-9417-39a9ef63c842", "type": "concept", "title": "City Dionysia"}, {"id": "37039852-10a4-4ea0-9036-156cea56e76a", "type": "concept", "title": "Choregoi"}, {"id": "9eeacb51-619c-480b-9d8d-040ba8fb0357", "type": "concept", "title": "Audience citizenship"}, {"id": "9871107e-88fe-462f-b941-36555255e549", "type": "concept", "title": "Ritual and procession"}], "description": "Why learn it: Students connect performance to religion, politics, competition, and public identity in Athens."}, {"id": "73bedf50-585d-4d79-b725-2d7150b6cae6", "type": "subtopic", "title": "Tragedy as form", "children": [{"id": "adfde973-9fad-44ff-b0c4-a05f8aad3385", "type": "concept", "title": "Aeschylus"}, {"id": "4a096151-5317-47f2-96de-66985a650b1a", "type": "concept", "title": "Sophocles"}, {"id": "a0f0ad34-b1b7-4998-83a0-09df76e1af68", "type": "concept", "title": "Euripides"}, {"id": "bcc35870-fdfc-4c8c-b310-e47d47cf599c", "type": "concept", "title": "Aristotle's Poetics"}], "description": "Why learn it: Students study how plot, chorus, recognition, reversal, and catastrophe organize theatrical meaning."}, {"id": "4ebb3e1a-837f-4b33-9de8-bf3a893852d4", "type": "subtopic", "title": "Greek performance conventions", "children": [{"id": "2a57eda7-da37-4485-880d-b3536ad62e7a", "type": "concept", "title": "Theatron"}, {"id": "564b257b-29c1-48c2-833c-2e738c396dbc", "type": "concept", "title": "Orchestra"}, {"id": "9e629492-ba4c-457f-b3f6-f3a30bb4bc29", "type": "concept", "title": "Skene"}, {"id": "dc69856a-011f-43eb-a92b-9516231ebb70", "type": "concept", "title": "Ekkyklema and mechane"}], "description": "Why learn it: Students learn how masks, outdoor acoustics, chorus movement, music, and architecture shaped theatrical style."}]}, {"id": "8befa63b-9e02-4c65-a146-34c473892e3d", "type": "topic", "title": "Greek Comedy and Satyr Drama", "description": "Comedy complicates the idea that ancient theater was only noble tragedy. Students examine satire, obscenity, parody, music, fantasy, and public critique as theatrical tools.", "children": [{"id": "76921371-0c75-485e-9ea3-096ea95d0c63", "type": "subtopic", "title": "Old Comedy", "children": [{"id": "c27c65ce-5070-44cf-8e76-93a4225d2880", "type": "concept", "title": "Aristophanes"}, {"id": "228b0773-58dc-4a83-bd2c-5c99c881ae83", "type": "concept", "title": "Parabasis"}, {"id": "50787b85-e479-46a7-8d46-47edf47912e0", "type": "concept", "title": "Political satire"}, {"id": "4368fe77-b977-4b55-9897-ba18642b8dd9", "type": "concept", "title": "Comic chorus"}], "description": "Why learn it: Students learn how comic performance attacked public figures, policies, literary fashions, and social behavior."}, {"id": "2b364e81-9e55-4901-a82a-d4abd663952a", "type": "subtopic", "title": "New Comedy", "children": [{"id": "8eecb614-9a45-4ffa-a2d0-71c49d84c3d0", "type": "concept", "title": "Menander"}, {"id": "b78e9f14-289e-45c6-b5e7-4445888e741e", "type": "concept", "title": "Recognition plots"}, {"id": "2b0f8fce-dbd7-499b-8f6c-3adfa61fc73b", "type": "concept", "title": "Household conflict"}, {"id": "14fbcd5c-742f-42e0-95b0-7a9a18113d16", "type": "concept", "title": "Influence on Rome"}], "description": "Why learn it: Students trace comedy's shift toward domestic plots, stock characters, romance, and social misunderstanding."}, {"id": "af07fdc1-96b3-449a-8d28-b2cb927036d2", "type": "subtopic", "title": "Comic legacy", "children": [{"id": "0f704b8a-1b2c-425a-b2eb-e9c65bc7826b", "type": "concept", "title": "Types and masks"}, {"id": "1b6235b9-a76c-4603-8348-2a9a4b8b4a62", "type": "concept", "title": "Lazzi-like business"}, {"id": "ed75e82a-8966-4097-80f7-348402cf4b30", "type": "concept", "title": "Mistaken identity"}, {"id": "cf310407-a37a-42ac-81c7-8050707e47db", "type": "concept", "title": "Comic servants"}], "description": "Why learn it: Students connect ancient comedy to later European farce, commedia, sitcom structures, and social satire."}]}, {"id": "7e83c9e9-7144-4ea1-ae11-ac568bfec78b", "type": "topic", "title": "Roman Theater", "description": "Roman theater helps students understand adaptation, spectacle, empire, popular entertainment, and the transmission of Greek dramatic forms into later European traditions.", "children": [{"id": "42b0c57d-fca5-478d-94da-3a0179d3ee48", "type": "subtopic", "title": "Roman comedy", "children": [{"id": "a0bd7ca3-441d-4f9d-9735-7dbd9320807d", "type": "concept", "title": "Plautus"}, {"id": "4ea2d04c-d929-47cf-9f3f-dcb1366c0398", "type": "concept", "title": "Terence"}, {"id": "840a2ead-2af1-4158-8c6e-aa93e01d63fc", "type": "concept", "title": "Stock characters"}, {"id": "a461b847-6f9f-4de4-814d-6068c6771c1b", "type": "concept", "title": "Musicality and rhythm"}], "description": "Why learn it: Students study how Plautus and Terence adapted Greek models for Roman audiences."}, {"id": "657a6e4f-56a5-4478-8f13-e77762d6c1aa", "type": "subtopic", "title": "Roman tragedy and spectacle", "children": [{"id": "8fb3a31a-fb39-4a26-8a6a-278f643a22cc", "type": "concept", "title": "Senecan revenge tragedy"}, {"id": "3e87c74d-182d-4e74-926c-98454ede7740", "type": "concept", "title": "Declamatory style"}, {"id": "f953583d-75a6-4d6f-85e7-afc70cd02740", "type": "concept", "title": "Amphitheater culture"}, {"id": "e78bcd7c-c8e5-473d-bacd-5e37c8dae35f", "type": "concept", "title": "Mime and pantomime"}], "description": "Why learn it: Students examine Seneca, rhetoric, violence, and the blurred boundary between theater and public spectacle."}, {"id": "2637c300-e132-4090-9590-4b0a901f5e33", "type": "subtopic", "title": "Architecture and audience", "children": [{"id": "fac06e35-e725-4329-90da-4c26efbae6f5", "type": "concept", "title": "Scaenae frons"}, {"id": "e0b2eed4-08c6-41f1-8e05-192b00a30e9c", "type": "concept", "title": "Vomitoria"}, {"id": "99dfdd47-fa92-455b-9e2b-ca32de0819fa", "type": "concept", "title": "Social seating"}, {"id": "5167773f-b975-4def-bd8e-8f7915dc3f4f", "type": "concept", "title": "Urban entertainment"}], "description": "Why learn it: Students learn how permanent theaters, stage houses, and imperial patronage changed performance scale."}]}, {"id": "15090b74-ffe2-4144-927b-e48851bea762", "type": "topic", "title": "Classical Sanskrit, Chinese, and Japanese Performance Traditions", "description": "This section explores major non-Western classical traditions on their own terms and compares how performance theory, music, movement, space, and audience expectations differ across cultures.", "children": [{"id": "ae77c523-58e8-419a-a617-251e2ded0ac0", "type": "subtopic", "title": "Sanskrit drama and rasa", "children": [{"id": "0ca45cf5-92ee-4448-8692-5146ae28c88b", "type": "concept", "title": "Natyashastra"}, {"id": "348b4cdd-bb32-4c7a-9707-1f5fc062734a", "type": "concept", "title": "Rasa theory"}, {"id": "8d3219b5-3ed0-4511-9c5c-3fdef3821f61", "type": "concept", "title": "Kalidasa"}, {"id": "014a73aa-9816-422a-a650-dbec580ac55f", "type": "concept", "title": "Gesture and music"}], "description": "Why learn it: Students learn how classical Indian theater theorized emotional flavor, performance technique, and the integration of dance, music, and poetry."}, {"id": "a08bcc28-5f26-469f-a98e-c0c66b16751f", "type": "subtopic", "title": "Chinese theatrical traditions", "children": [{"id": "5fc4e306-026b-4199-bdf0-c86a52ad954d", "type": "concept", "title": "Zaju"}, {"id": "2e6b1ede-9af3-4c31-8331-5366a747efa7", "type": "concept", "title": "Kunqu"}, {"id": "811e6869-39d0-4388-b945-479a9e0aeadd", "type": "concept", "title": "Jingju/Peking opera"}, {"id": "be44a43a-d392-4736-8e14-751b6830633d", "type": "concept", "title": "Role categories"}], "description": "Why learn it: Students survey performance conventions that combine song, movement, role types, costume, and stylized gesture."}, {"id": "a6cb80d5-f3cc-47da-9a31-0ec5f04a3ad6", "type": "subtopic", "title": "Japanese Noh, Kyogen, Bunraku, and Kabuki", "children": [{"id": "774a4d50-e4b4-4d64-848a-48b2ce653c8d", "type": "concept", "title": "Zeami"}, {"id": "9dfa5ea0-c204-4723-834b-53ff62ba82e7", "type": "concept", "title": "Masks and yugen"}, {"id": "c2b75c26-e8bb-47f0-b480-a0371967e8a4", "type": "concept", "title": "Puppet dramaturgy"}, {"id": "747bc04c-b07e-49f9-92c7-c6304a34072e", "type": "concept", "title": "Onnagata and mie"}], "description": "Why learn it: Students compare restraint, comic interlude, puppet performance, and popular spectacle across Japanese forms."}]}, {"id": "8132a1f4-1642-44c5-a18b-2ef7dcce5aaa", "type": "topic", "title": "Medieval Drama", "description": "Medieval theater shows how performance survived and transformed through liturgy, civic pageantry, guild structures, morality plays, and public spectacle. Students learn to read theater as both religious practice and urban social event.", "children": [{"id": "211e8905-70e3-4786-9057-c6fd8e82d45a", "type": "subtopic", "title": "Liturgical drama", "children": [{"id": "42eb398d-5b58-41e7-be2b-545b7cd172d9", "type": "concept", "title": "Quem quaeritis"}, {"id": "6241069b-103a-4f4d-9df3-acefa7a5536d", "type": "concept", "title": "Processional performance"}, {"id": "9f708be8-16b6-4e85-b597-0b19b1a7bd65", "type": "concept", "title": "Church space"}, {"id": "583f3a05-815b-4c42-a406-e87d732418bd", "type": "concept", "title": "Latin and vernacular shifts"}], "description": "Why learn it: Students trace theatricality inside worship and understand the relationship between ritual, music, language, and staging."}, {"id": "7b002d93-867b-4ebe-b4a2-1eb5c98b3c87", "type": "subtopic", "title": "Mystery and cycle plays", "children": [{"id": "99e710b8-354a-4adf-97c9-269acdd3fab8", "type": "concept", "title": "Guild sponsorship"}, {"id": "c69103c0-b4ce-4f79-bca2-4196b28a1d57", "type": "concept", "title": "Pageant wagons"}, {"id": "9f7d54a0-65fa-4ab4-bdfe-4b7686a87aee", "type": "concept", "title": "York and Wakefield cycles"}, {"id": "0b82fe25-de34-4a83-8aef-131850955adb", "type": "concept", "title": "Community performance"}], "description": "Why learn it: Students study large-scale civic biblical drama and the social organization behind it."}, {"id": "9b6c7ab4-8d12-485c-8de8-a6345c0080fd", "type": "subtopic", "title": "Morality plays and allegory", "children": [{"id": "64289955-bfcc-4614-a8f0-30b6d334cda8", "type": "concept", "title": "Everyman"}, {"id": "4e1056bc-5e1d-4b23-8d32-ce12a8170f6b", "type": "concept", "title": "Vice figures"}, {"id": "1c79cc44-8157-4736-9347-5a00741d34f1", "type": "concept", "title": "Allegorical characters"}, {"id": "eb9dd85a-a5b4-4bde-8ab2-4d9cd881dd03", "type": "concept", "title": "Memento mori"}], "description": "Why learn it: Students analyze how personified abstractions create dramatic conflict and ethical instruction."}]}, {"id": "da32e839-bd71-4c83-93a2-da7414524caf", "type": "topic", "title": "Commedia dell'Arte", "description": "Commedia dell'arte teaches students about actor-centered theater, improvisation, touring companies, masks, lazzi, and the long life of stock characters in European performance.", "children": [{"id": "85928a72-f894-4ec8-9791-70ce210210d9", "type": "subtopic", "title": "Professional companies", "children": [{"id": "7da7befa-692b-4bb1-8f00-4e2d7259e0d6", "type": "concept", "title": "Gelosi"}, {"id": "c2985baf-1bf5-4c96-b3cf-4b4fc7202f79", "type": "concept", "title": "Touring circuits"}, {"id": "771bc27c-add8-44f6-9b4c-22da4d880701", "type": "concept", "title": "Women performers"}, {"id": "ac8adfff-9ced-4bce-a2ef-16898faff777", "type": "concept", "title": "Patronage"}], "description": "Why learn it: Students learn how traveling troupes organized repertory, business, roles, and audience appeal."}, {"id": "25fc6ac8-faf8-480e-bbd5-44bac6978bc2", "type": "subtopic", "title": "Masks and stock characters", "children": [{"id": "847c3d3a-6756-4470-acda-ba115c2e9553", "type": "concept", "title": "Pantalone"}, {"id": "25b8a461-725f-4f97-8f6c-7a961c111d71", "type": "concept", "title": "Dottore"}, {"id": "4771b454-2fba-4d40-a50c-78a1e04d8d7c", "type": "concept", "title": "Arlecchino"}, {"id": "5e2f6cea-f1bb-422d-bbd1-94e6b9b8ef08", "type": "concept", "title": "Innamorati"}], "description": "Why learn it: Students analyze how repeated types generate comic situations while still allowing actor invention."}, {"id": "70f9c8c2-22d4-40f4-a1ed-538891b1dce0", "type": "subtopic", "title": "Improvisation and scenarios", "children": [{"id": "ac5b0c7a-6af7-42c3-84a6-e1601c5e9e19", "type": "concept", "title": "Canovacci"}, {"id": "bede998e-fdec-475c-8978-c79fa5c04294", "type": "concept", "title": "Lazzi"}, {"id": "c1fb36a5-efb4-46a6-acf9-de2626d1d656", "type": "concept", "title": "Physical comedy"}, {"id": "c9673e0a-279d-420c-bcda-4ed0314d7e42", "type": "concept", "title": "Improvised dialogue"}], "description": "Why learn it: Students study structured improvisation as a disciplined performance system rather than random invention."}]}, {"id": "dcc474ca-4cc4-4c1e-901f-6d78ceecb319", "type": "topic", "title": "Elizabethan Theater and Shakespeare", "description": "This topic places Shakespeare inside a broader early modern theater industry. Students examine public playhouses, repertory companies, censorship, acting practice, audience behavior, and dramatic language.", "children": [{"id": "cb3a5526-d980-4ad9-bb81-4b6bee0308be", "type": "subtopic", "title": "London theater industry", "children": [{"id": "fd79f4dd-fab2-4494-8261-8adc9e9fbc17", "type": "concept", "title": "Lord Chamberlain's Men"}, {"id": "379cb4ec-9c8b-4da9-9eb2-be3cec192d23", "type": "concept", "title": "The Globe"}, {"id": "02405f4e-cae7-4d44-854d-4e3cd2d92748", "type": "concept", "title": "Master of the Revels"}, {"id": "3d9e23b8-40ed-48f1-bd06-6ece0cdae246", "type": "concept", "title": "Repertory system"}], "description": "Why learn it: Students learn how companies, shareholders, apprentices, playhouses, and censorship shaped the plays that survived."}, {"id": "31e1214d-6dbe-434b-bf54-734f88ced502", "type": "subtopic", "title": "Shakespeare and contemporaries", "children": [{"id": "d7f427ac-666f-40b0-8e7a-63a404d99c74", "type": "concept", "title": "Marlowe"}, {"id": "da23e17a-5d8b-4e19-ba0b-38fac3419ac1", "type": "concept", "title": "Jonson"}, {"id": "e017b80c-c646-4ebe-a5c2-ef4bd466801e", "type": "concept", "title": "Kyd"}, {"id": "2febd386-1eb8-41cd-bd6a-038b7758966e", "type": "concept", "title": "History, comedy, tragedy, romance"}], "description": "Why learn it: Students study major dramatic forms and writers without reducing the period to a single author."}, {"id": "023718eb-df81-4fdf-9b2a-013e5951587d", "type": "subtopic", "title": "Performance conditions", "children": [{"id": "151ebccb-a2cc-4695-bfdb-05f7dd54dee4", "type": "concept", "title": "Thrust stage"}, {"id": "18efaf9c-d6e1-49ad-873d-c50cfdfb9566", "type": "concept", "title": "Minimal scenery"}, {"id": "9580e9b0-5905-4736-998d-ac61c835731c", "type": "concept", "title": "Shared light"}, {"id": "467813ba-7209-4057-acdc-fcbaf77a22f9", "type": "concept", "title": "Blank verse"}], "description": "Why learn it: Students connect architecture and conventions to acting choices, audience relationship, and dramaturgy."}]}, {"id": "03272825-667f-44c8-b5c8-6d6964938292", "type": "topic", "title": "Spanish Golden Age", "description": "Spanish Golden Age drama broadens early modern theater beyond England. Students learn about corrales, honor codes, religious drama, national identity, and the commercial power of playwrights such as Lope de Vega and Calderon.", "children": [{"id": "e9a1ff7d-5607-490e-92db-a7c43e4bd2f2", "type": "subtopic", "title": "Comedia nueva", "children": [{"id": "1cb4cfd5-66a6-44c6-94a5-3063fc624064", "type": "concept", "title": "Lope de Vega"}, {"id": "0450612e-4eb3-4454-81d7-e4b6b0123691", "type": "concept", "title": "Three-act structure"}, {"id": "640bd17e-12af-4ecd-9cc8-229699b9751c", "type": "concept", "title": "Honor plots"}, {"id": "fd456038-d0d8-4007-8120-8b085acca106", "type": "concept", "title": "Genre mixture"}], "description": "Why learn it: Students study the flexible three-act form and its mixture of tragic, comic, sacred, and popular material."}, {"id": "40e8ef94-cb9f-416c-8d99-c2853b0b8002", "type": "subtopic", "title": "Performance spaces and audiences", "children": [{"id": "50515a37-9ccb-4b47-af02-e997a9981cb4", "type": "concept", "title": "Corral architecture"}, {"id": "8b0adb2f-1b9d-478f-a065-65b8b0f702ea", "type": "concept", "title": "Mosqueteros"}, {"id": "1258dbc6-ee25-46ab-b464-9d9f7cef612f", "type": "concept", "title": "Cazuela"}, {"id": "fff69eab-6d08-48b2-b632-b5188d137176", "type": "concept", "title": "Company organization"}], "description": "Why learn it: Students learn how corrales shaped staging, audience composition, and theatrical business."}, {"id": "57b3c82b-dae3-4d1f-ae0e-241a89c3f2e3", "type": "subtopic", "title": "Religious and philosophical drama", "children": [{"id": "b2fd6966-5e52-4b53-93c8-a148a7ca5003", "type": "concept", "title": "Calderon"}, {"id": "2d8b680d-5c99-484f-b5e0-a02242b8336f", "type": "concept", "title": "Autos sacramentales"}, {"id": "a9a79bea-5b90-40c7-b065-1d4800b78aea", "type": "concept", "title": "Free will"}, {"id": "683c525b-1d07-4fcc-be93-fe5d5935d952", "type": "concept", "title": "Theater and Catholic culture"}], "description": "Why learn it: Students explore autos sacramentales and metaphysical themes in Calderon's work."}]}, {"id": "0317022e-dadb-428d-8dc0-a29d3366a24c", "type": "topic", "title": "French Neoclassicism", "description": "French neoclassicism introduces students to rules, academies, decorum, state patronage, and the formal pressure of court culture. The topic helps students understand how theatrical taste becomes institutionalized.", "children": [{"id": "b0252db7-e4cb-4eda-b70c-904590289d6f", "type": "subtopic", "title": "Rules and dramatic theory", "children": [{"id": "a8ca7f5c-d3f9-4765-b2a6-9459da5ff161", "type": "concept", "title": "Three unities"}, {"id": "b7d80209-fc11-46b3-8b4d-19eece4bb946", "type": "concept", "title": "Decorum"}, {"id": "5173d7be-a37c-416c-b0e9-05ea018ccc20", "type": "concept", "title": "Verisimilitude"}, {"id": "b187a940-9a46-4be1-87c2-10d96ef6d5cf", "type": "concept", "title": "Academie Francaise"}], "description": "Why learn it: Students learn how unity, decorum, vraisemblance, and genre hierarchy shaped playwriting and criticism."}, {"id": "d0c79c9f-8811-45e1-8421-3afb856bfd62", "type": "subtopic", "title": "Tragedy and comedy", "children": [{"id": "43781440-dc54-4d4f-9749-72ec4b56ba3f", "type": "concept", "title": "Corneille"}, {"id": "893b24e8-7c16-4647-895a-92be5b65ae04", "type": "concept", "title": "Racine"}, {"id": "b3274979-3731-4f54-8795-a8d688c171bb", "type": "concept", "title": "Moliere"}, {"id": "5986b220-6753-4494-b6be-0a787347a9b7", "type": "concept", "title": "Alexandrine verse"}], "description": "Why learn it: Students compare Corneille, Racine, and Moliere as different responses to classical ideals and social critique."}, {"id": "3f54654e-6274-47e3-8e95-fcf06447d65a", "type": "subtopic", "title": "Court culture and institutions", "children": [{"id": "7534f3af-329d-49e9-98b5-d86d3a272325", "type": "concept", "title": "Louis XIV"}, {"id": "0dd24cfc-1bd0-48c9-8337-ad1ffbd9d9e4", "type": "concept", "title": "Comedie-Francaise"}, {"id": "62605c7e-19f4-43a8-9d3a-439b08fd9dda", "type": "concept", "title": "Royal patronage"}, {"id": "15d92cc1-5329-4660-9731-31e3e2add105", "type": "concept", "title": "Censorship"}], "description": "Why learn it: Students connect theatrical form to absolutism, patronage, censorship, and the rise of national theater."}]}, {"id": "596f5579-b881-4065-9b0d-87f22d0e340a", "type": "topic", "title": "Restoration Theater", "description": "Restoration theater reveals how politics, gender, celebrity, scenic technology, and commercial entertainment changed after the reopening of English theaters in 1660.", "children": [{"id": "6702f978-91a6-4015-a4f5-812e82d2945c", "type": "subtopic", "title": "Reopening and theater patents", "children": [{"id": "ce288912-601b-47cb-956d-dd3a93b6d0d1", "type": "concept", "title": "Charles II"}, {"id": "de6a80d0-607c-48f0-a8c6-492a5c107efb", "type": "concept", "title": "Patent theaters"}, {"id": "6b51b99d-7333-4009-93f9-a5fadda16bc3", "type": "concept", "title": "Duke's Company"}, {"id": "fa1356ff-7f0a-4e8d-87d9-3e13b214190b", "type": "concept", "title": "King's Company"}], "description": "Why learn it: Students learn how monarchy, licensing, and patents reshaped English theater after the Puritan closure."}, {"id": "b6f336ac-307e-4b5e-8ee5-bfa03c6d231f", "type": "subtopic", "title": "Women on stage and celebrity", "children": [{"id": "be1ae16f-a7b5-4fb8-9dac-6529c5e26ee9", "type": "concept", "title": "Nell Gwyn"}, {"id": "3c2fa4b9-e082-4464-b2c7-91af27647add", "type": "concept", "title": "Breeches roles"}, {"id": "54a40eb3-c8f7-4b68-8157-2d7409847057", "type": "concept", "title": "Celebrity culture"}, {"id": "9a256f33-8b0b-46b9-98b5-59374c3a6df4", "type": "concept", "title": "Gendered spectatorship"}], "description": "Why learn it: Students examine the significance and limits of actresses entering the professional English stage."}, {"id": "0103fae7-43c5-4eed-a17f-6bb6cb2ebecc", "type": "subtopic", "title": "Comedy of manners and scenic spectacle", "children": [{"id": "677761a3-0175-4592-9a89-240cbd382310", "type": "concept", "title": "Wycherley"}, {"id": "c40b0b01-6b29-4c3a-9f77-6f20e262f5f0", "type": "concept", "title": "Congreve"}, {"id": "6b7249e6-f4b8-414b-aa83-9c2b48d23e10", "type": "concept", "title": "Proscenium staging"}, {"id": "b66d87d8-f9a8-45f6-a66b-322ab0efa815", "type": "concept", "title": "Moveable scenery"}], "description": "Why learn it: Students analyze wit, social performance, sexual politics, and new stage technologies."}]}, {"id": "271ac3ef-11df-4084-b10b-d3cf59d7afc3", "type": "topic", "title": "18th-Century Theater", "description": "The 18th century helps students see theater as a modern public institution shaped by sentiment, reform, censorship, star actors, colonial exchange, and expanding middle-class audiences.", "children": [{"id": "74126a5a-e4d8-4a83-90fb-6a0dfa47063c", "type": "subtopic", "title": "Sentimental comedy and bourgeois drama", "children": [{"id": "5b1a92cd-b533-4e7e-9c9e-0cae49d05e3a", "type": "concept", "title": "Steele"}, {"id": "89e528e6-5993-4bc3-a803-3938e0659eef", "type": "concept", "title": "Diderot"}, {"id": "8c378814-6985-4191-bc0b-d2e393f5ca88", "type": "concept", "title": "Domestic tragedy"}, {"id": "fd3b7360-f6c4-4d14-b762-6fe54c39a902", "type": "concept", "title": "Middle-class spectatorship"}], "description": "Why learn it: Students examine changing audience values around virtue, feeling, family, and class."}, {"id": "4f1f6a7f-82e6-4d8c-a750-ab87eedd8295", "type": "subtopic", "title": "Actors and managers", "children": [{"id": "8f9dad11-d82a-4d57-88fd-e945d506a431", "type": "concept", "title": "David Garrick"}, {"id": "7fe99efb-7892-42ac-9f61-0bc2f4911649", "type": "concept", "title": "Sarah Siddons"}, {"id": "10a6ed76-0782-404f-9890-7264c4458bfe", "type": "concept", "title": "Rehearsal reform"}, {"id": "11511440-b78e-44ff-aa71-67087a5d8b74", "type": "concept", "title": "Star system"}], "description": "Why learn it: Students learn how performers and actor-managers changed rehearsal, repertory, celebrity, and theatrical business."}, {"id": "b7a7e7fc-83a1-4ca9-b960-d43e404ef2bf", "type": "subtopic", "title": "Theater and public culture", "children": [{"id": "8667ef09-4866-4cd1-b9c1-6db14ed27f81", "type": "concept", "title": "Licensing Act of 1737"}, {"id": "9f01ec53-92f5-47f6-a0f0-9c706a2040e3", "type": "concept", "title": "Coffeehouse culture"}, {"id": "4a48747d-9bb2-4a06-bde9-30328eb3ea8a", "type": "concept", "title": "Theater criticism"}, {"id": "1313920a-71af-44f1-87e7-817ba9744b10", "type": "concept", "title": "Colonial performance circuits"}], "description": "Why learn it: Students connect performance to censorship, criticism, nationalism, empire, and public debate."}]}, {"id": "ce6b0510-bd78-4010-912c-fb5959621e0c", "type": "topic", "title": "Theater Architecture and Performance Conventions", "description": "Architecture and convention run through every period in the course. This concluding topic asks students to compare spaces, technologies, audience arrangements, and performance rules across historical traditions.", "children": [{"id": "118b3c5c-8e3d-4762-a9b2-98d7c228e326", "type": "subtopic", "title": "Space and spectatorship", "children": [{"id": "b42bb321-7a34-4631-bfe1-6ad096ea8f40", "type": "concept", "title": "Amphitheaters"}, {"id": "18950f06-b51d-478d-b15a-77cc029fc18b", "type": "concept", "title": "Thrust stages"}, {"id": "592887a6-27e1-409d-a278-ba5d6d5b201c", "type": "concept", "title": "Corrales"}, {"id": "5ed92865-9d6a-4561-a0c9-74190be8b1e8", "type": "concept", "title": "Proscenium arches"}], "description": "Why learn it: Students learn how audience placement affects acting style, social behavior, visibility, and power."}, {"id": "2213054b-52b4-46b8-9225-8aecda59c27a", "type": "subtopic", "title": "Scenery, costume, and technology", "children": [{"id": "775c10e8-b79e-4d1b-91e6-f82feaee5a74", "type": "concept", "title": "Masks"}, {"id": "51502cfa-417b-4612-a6df-bdd4946b9068", "type": "concept", "title": "Machinery"}, {"id": "39467a90-070d-4f88-81ce-5c3396ad464d", "type": "concept", "title": "Perspective scenery"}, {"id": "d379c839-d0bd-4b7c-b4c9-314a694d878e", "type": "concept", "title": "Lighting before electricity"}], "description": "Why learn it: Students trace how material conditions shaped dramatic form and theatrical imagination."}, {"id": "23cbb10f-0fb2-47df-a31c-67cdd67415de", "type": "subtopic", "title": "Conventions across cultures", "children": [{"id": "e6c3045c-7764-43e1-b3c0-5f1644cb85f3", "type": "concept", "title": "Chorus"}, {"id": "bfd5c44b-b9d8-476a-a000-b595593c5ae4", "type": "concept", "title": "Narration"}, {"id": "d9605469-c649-4369-af17-532b920285b4", "type": "concept", "title": "Stylized gesture"}, {"id": "4489e375-04dd-452a-8598-1355ff5eee7b", "type": "concept", "title": "Music and dance integration"}], "description": "Why learn it: Students compare theatrical rules without assuming one tradition is the standard."}]}], "dbBacked": true}$thi1json$::jsonb,
