values
  ('052004d7-1633-4422-bfd9-2bac9b579111', 'e3f4a5b6-7c8d-4e33-8a23-3b4c5d6e7f33', null, 'topic'::public.curated_course_node_type, 'Theater Historiography and Research Methods', 'A world-class theater history course starts by asking how history is made. Students learn that theater history is reconstructed from scripts, buildings, images, reviews, account books, censorship records, costumes, oral traditions, and performance traces rather than from performance itself.', 0),
  ('445351fb-222a-41ba-8855-2ecb2aae11bc', 'e3f4a5b6-7c8d-4e33-8a23-3b4c5d6e7f33', '052004d7-1633-4422-bfd9-2bac9b579111', 'subtopic'::public.curated_course_node_type, 'What counts as evidence', 'Why learn it: Students learn to read different kinds of historical evidence and understand what each source can and cannot prove.', 0),
  ('2f0c87f5-6c71-4a82-86f4-59254aa41753', 'e3f4a5b6-7c8d-4e33-8a23-3b4c5d6e7f33', '445351fb-222a-41ba-8855-2ecb2aae11bc', 'concept'::public.curated_course_node_type, 'Playtexts and manuscripts', null, 0),
