  ('cb59d71f-e34f-4095-b964-2363dbb6638c', 'e3f4a5b6-7c8d-4e33-8a23-3b4c5d6e7f33', '052004d7-1633-4422-bfd9-2bac9b579111', 'subtopic'::public.curated_course_node_type, 'Historiography and canon formation', 'Why learn it: The point is to see theater history as an argument shaped by archives, institutions, colonial histories, translation, and access.', 1),
