  ('ba555745-9952-4c7c-80e3-63b658c40842', 'e3f4a5b6-7c8d-4e33-8a23-3b4c5d6e7f33', '052004d7-1633-4422-bfd9-2bac9b579111', 'subtopic'::public.curated_course_node_type, 'Research habits', 'Why learn it: Students practice citation, source evaluation, and responsible use of digital archives.', 2),
