  ('ce1d6c4e-d58c-48db-8710-7fa2f1ca0bb0', 'e3f4a5b6-7c8d-4e33-8a23-3b4c5d6e7f33', 'ba555745-9952-4c7c-80e3-63b658c40842', 'concept'::public.curated_course_node_type, 'Scholarly databases', null, 3),
  ('03e5bb9c-128b-42b4-a976-d8ae45ae05cd', 'e3f4a5b6-7c8d-4e33-8a23-3b4c5d6e7f33', null, 'topic'::public.curated_course_node_type, 'Greek Theater and Tragedy', 'Greek theater gives students a foundation in Western dramatic structure, civic performance, festival culture, chorus, myth, and architectural conventions. The goal is not reverence alone, but historical understanding of how tragedy functioned in its own society.', 1),
  ('08ef3fb8-0a3b-4a77-88af-3d9cb5c6c6f8', 'e3f4a5b6-7c8d-4e33-8a23-3b4c5d6e7f33', '03e5bb9c-128b-42b4-a976-d8ae45ae05cd', 'subtopic'::public.curated_course_node_type, 'Dionysian festivals and civic context', 'Why learn it: Students connect performance to religion, politics, competition, and public identity in Athens.', 0),
  ('c294efdd-8b05-4a26-9417-39a9ef63c842', 'e3f4a5b6-7c8d-4e33-8a23-3b4c5d6e7f33', '08ef3fb8-0a3b-4a77-88af-3d9cb5c6c6f8', 'concept'::public.curated_course_node_type, 'City Dionysia', null, 0),
