  ('9871107e-88fe-462f-b941-36555255e549', 'e3f4a5b6-7c8d-4e33-8a23-3b4c5d6e7f33', '08ef3fb8-0a3b-4a77-88af-3d9cb5c6c6f8', 'concept'::public.curated_course_node_type, 'Ritual and procession', null, 3),
  ('73bedf50-585d-4d79-b725-2d7150b6cae6', 'e3f4a5b6-7c8d-4e33-8a23-3b4c5d6e7f33', '03e5bb9c-128b-42b4-a976-d8ae45ae05cd', 'subtopic'::public.curated_course_node_type, 'Tragedy as form', 'Why learn it: Students study how plot, chorus, recognition, reversal, and catastrophe organize theatrical meaning.', 1),
