  ('bcc35870-fdfc-4c8c-b310-e47d47cf599c', 'e3f4a5b6-7c8d-4e33-8a23-3b4c5d6e7f33', '73bedf50-585d-4d79-b725-2d7150b6cae6', 'concept'::public.curated_course_node_type, 'Aristotle''s Poetics', null, 3),
  ('4ebb3e1a-837f-4b33-9de8-bf3a893852d4', 'e3f4a5b6-7c8d-4e33-8a23-3b4c5d6e7f33', '03e5bb9c-128b-42b4-a976-d8ae45ae05cd', 'subtopic'::public.curated_course_node_type, 'Greek performance conventions', 'Why learn it: Students learn how masks, outdoor acoustics, chorus movement, music, and architecture shaped theatrical style.', 2),
  ('2a57eda7-da37-4485-880d-b3536ad62e7a', 'e3f4a5b6-7c8d-4e33-8a23-3b4c5d6e7f33', '4ebb3e1a-837f-4b33-9de8-bf3a893852d4', 'concept'::public.curated_course_node_type, 'Theatron', null, 0),
