  ('dc69856a-011f-43eb-a92b-9516231ebb70', 'e3f4a5b6-7c8d-4e33-8a23-3b4c5d6e7f33', '4ebb3e1a-837f-4b33-9de8-bf3a893852d4', 'concept'::public.curated_course_node_type, 'Ekkyklema and mechane', null, 3),
  ('8befa63b-9e02-4c65-a146-34c473892e3d', 'e3f4a5b6-7c8d-4e33-8a23-3b4c5d6e7f33', null, 'topic'::public.curated_course_node_type, 'Greek Comedy and Satyr Drama', 'Comedy complicates the idea that ancient theater was only noble tragedy. Students examine satire, obscenity, parody, music, fantasy, and public critique as theatrical tools.', 2),
  ('76921371-0c75-485e-9ea3-096ea95d0c63', 'e3f4a5b6-7c8d-4e33-8a23-3b4c5d6e7f33', '8befa63b-9e02-4c65-a146-34c473892e3d', 'subtopic'::public.curated_course_node_type, 'Old Comedy', 'Why learn it: Students learn how comic performance attacked public figures, policies, literary fashions, and social behavior.', 0),
  ('c27c65ce-5070-44cf-8e76-93a4225d2880', 'e3f4a5b6-7c8d-4e33-8a23-3b4c5d6e7f33', '76921371-0c75-485e-9ea3-096ea95d0c63', 'concept'::public.curated_course_node_type, 'Aristophanes', null, 0),
