  ('2b364e81-9e55-4901-a82a-d4abd663952a', 'e3f4a5b6-7c8d-4e33-8a23-3b4c5d6e7f33', '8befa63b-9e02-4c65-a146-34c473892e3d', 'subtopic'::public.curated_course_node_type, 'New Comedy', 'Why learn it: Students trace comedy''s shift toward domestic plots, stock characters, romance, and social misunderstanding.', 1),
