  ('7e83c9e9-7144-4ea1-ae11-ac568bfec78b', 'e3f4a5b6-7c8d-4e33-8a23-3b4c5d6e7f33', null, 'topic'::public.curated_course_node_type, 'Roman Theater', 'Roman theater helps students understand adaptation, spectacle, empire, popular entertainment, and the transmission of Greek dramatic forms into later European traditions.', 3),
  ('42b0c57d-fca5-478d-94da-3a0179d3ee48', 'e3f4a5b6-7c8d-4e33-8a23-3b4c5d6e7f33', '7e83c9e9-7144-4ea1-ae11-ac568bfec78b', 'subtopic'::public.curated_course_node_type, 'Roman comedy', 'Why learn it: Students study how Plautus and Terence adapted Greek models for Roman audiences.', 0),
