  ('15090b74-ffe2-4144-927b-e48851bea762', 'e3f4a5b6-7c8d-4e33-8a23-3b4c5d6e7f33', null, 'topic'::public.curated_course_node_type, 'Classical Sanskrit, Chinese, and Japanese Performance Traditions', 'This section explores major non-Western classical traditions on their own terms and compares how performance theory, music, movement, space, and audience expectations differ across cultures.', 4),
