  ('211e8905-70e3-4786-9057-c6fd8e82d45a', 'e3f4a5b6-7c8d-4e33-8a23-3b4c5d6e7f33', '8132a1f4-1642-44c5-a18b-2ef7dcce5aaa', 'subtopic'::public.curated_course_node_type, 'Liturgical drama', 'Why learn it: Students trace theatricality inside worship and understand the relationship between ritual, music, language, and staging.', 0),
